import math

def sinusoidal_positional_encoding(position, dim):
    pe = []
    for i in range(dim):
        if i % 2 == 0:
            pe.append(math.sin(position / (10000 ** (i / dim))))
        else:
            pe.append(math.cos(position / (10000 ** ((i - 1) / dim))))
    return pe

for pos in [0, 1, 2]:
    enc = sinusoidal_positional_encoding(pos, 4)
    print(f"pos {pos}: {[round(x, 3) for x in enc]}")

